/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
import re
for pat in ['Integrity*','Midwest*','Leju*','KUBIENT*']:
 for f in Path('/docs').glob(pat):
  print(f.name)
  parts=re.split(r'--- page (\\d+) ---',f.read_text())
  for i in range(1,len(parts),2):
   lines=parts[i+1].splitlines()
   for j,l in enumerate(lines):
    if re.search('audit|inspect|examin|books|access.*record',l,re.I): print('PAGE',parts[i],'\\n','\\n'.join(lines[max(0,j-3):j+12]))
PY"

